css:
.bible-content-139856305464704-surface { background-color: #ffffff; color: #202020; }
.passage-actions { border-radius: 12px; padding: 3px; }
.passage-actions button { min-width: 26px; min-height: 26px; padding: 2px; }
textview.bible-content-139856305464704, textview.bible-content-139856305464704 text { background-color: #ffffff; color: #202020; }
textview.bible-content-139856305464704 text selection { background-color: #004a99; color: #ffffff; }
textview.bible-content-139856305464704 text link { color: #003f87; }
textview.bible-content-139856305464704.study-reader, textview.bible-content-139856305464704.study-reader text { background-color: transparent; color: @sidebar_fg_color; }
/* GTK owns focus-visible/modality. Draw on the text CSS node so its opaque
   background cannot cover the focus mark. Inset shadows do not change layout. */
textview.bible-content-139856305464704:focus-visible text { box-shadow: inset 2px 0 0 #003f87; }
textview.bible-content-139856305464704:dir(rtl):focus-visible text { box-shadow: inset -2px 0 0 #003f87; }
